#!/usr/bin/env node
/* Generates the reference documentation from the source of truth:
 *   docs/LANGUAGE.md  <- src/engine/libdoc.js, sprites, palette
 *   docs/VISUAL.md    <- the block schema in src/editor/visual-compile.js and the starter projects
 * Run:  node tools/docs.js   (or: npm run build). Never edit the generated files by hand. */
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const build = require('./build.js');

function load() {
  const ctx = vm.createContext({ console, TextEncoder, TextDecoder, Math, Date, JSON, Object, Array, Number, String, Promise, Error });
  vm.runInContext(build.coreSource(), ctx, { filename: 'core.js' });
  return vm.runInContext('({ LIBDOC, INPUTDOC, SP, SPRITE_ART, PAL, COLOR_NAMES, VB, VNAMES, VTEMPLATES, GAMES, BASE, QR, toURL, urlSegs, min, U8 })', ctx);
}

const md = s => s.replace(/\n{3,}/g, '\n\n').trim() + '\n';
const HEADER = '<!-- GENERATED by tools/docs.js from the source code. Do not edit by hand. -->\n\n';

function language(A) {
  const out = [HEADER];
  out.push(`# QRG language reference

A QRG game is **JavaScript**: the body of a function that ends by returning a function that is called 60 times per second.
Everything below is available to the game without importing anything. The whole program has to fit in a QR code
(about 2.9 KB after compression), so it is meant to be short.

\`\`\`js
let x = 120, y = 110, score = 0;          // your own variables

return i => {                             // runs every frame; \`i\` holds the input
  cls(NAVY);                              // library functions are just in scope
  if (i.l) x -= 2;                        // d-pad / arrow key / swipe left
  if (i.A) { score++; s(600); }           // A button / tap
  r(x, y, 16, 16, ORANGE);
  t('SCORE ' + score, 4, 4, WHITE);
};
\`\`\`

## The screen

* 256 × 240 pixels, **16 colors** (the palette below), no anti-aliasing. Colors are numbers 0-15 or the names \`BLACK\` … \`PEACH\`.
* Text uses a built-in 3 × 5 pixel font; sprites are 8 × 8 pixels, one bit per pixel, drawn in any palette color.
* The game runs at a fixed 60 frames per second on every device.

## Rules of the language

* Your variables may have **any name**, even the name of a library function: \`let r = 5\` is fine (it only hides \`r()\` inside your game).
* A game must end with \`return i => { ... }\`. Errors are shown on the screen and sent to the editor.
* A game runs in a sandbox: it cannot use the network, cookies, the page, or other games' data. \`save\` / \`load\` are the only way to keep data.
* **Memory is private to the game.** \`save\` stores into a memory slot derived from a fingerprint of the game's code, so a game can keep
  things (a high score, a pet that is still alive tomorrow) without ever seeing another game's data. The ↺ button in the game view forgets it.
* Randomness: \`R(n)\`, \`rand()\` and friends use \`Math.random\` unless you call \`seed(n)\`.

## Input — the argument of the frame function

| Field | Meaning |
|---|---|
${A.INPUTDOC.map(([k, d]) => `| \`${k}\` | ${d} |`).join('\n')}

Gestures are mapped onto these fields: a **swipe** becomes a direction press (and repeats while the finger keeps dragging),
a **tap** becomes \`A\`. The on-screen pad and the keyboard (arrows, Z / Space = A, X = B, Enter = Start) feed the same fields.

## Library
`);
  let g = '';
  for (const e of A.LIBDOC.filter(e => !e.hide)) {
    if (e.g !== g) { g = e.g; out.push(`\n### ${g}\n`); }
    out.push(`**\`${e.s}\`** — ${e.d}\n`);
    if (e.e) out.push('```js\n' + e.e + '\n```\n');
  }
  out.push(`\n## Palette\n\n| # | Name | Color |\n|---|---|---|\n${A.PAL.map((c, k) => `| ${k} | \`${A.COLOR_NAMES[k]}\` | \`${c}\` |`).join('\n')}\n`);
  out.push(`\n## Built-in sprites\n\nUse them by name: \`d('heart', x, y, RED, 2)\` or \`d(SP.heart, x, y, RED, 2)\`.\n\n`);
  out.push('```text\n' + Object.keys(A.SP).join('  ') + '\n```\n');
  out.push(`\nA sprite is just 8 numbers, so you can make your own: each number is one row, the most significant bit is the left pixel.\n\n\`\`\`js\nd([24, 60, 126, 255, 255, 126, 60, 24], 100, 100, YELLOW, 4);\n\`\`\`\n`);
  out.push(`\n## Limits\n\n* About **2.9 KB** of compressed code (QR version 40). Typical games are 400–1500 bytes of code; the two large demos, *Tactics* and *Tiny Pet*, are 3–4 KB.\n* Storage: 32 keys per game, about 1.5 KB per value.\n* Sprites are 8 × 8, one color each; the screen has 16 fixed colors.\n`);
  return md(out.join('\n'));
}

function visual(A) {
  const out = [HEADER];
  out.push(`# The visual editor

The visual editor lets you make a game without typing code: **draw** sprites, **place** them on the screen and describe
what happens with **rules**. The editor writes an ordinary QRG program for you (open the *Code* tab to read it, or press
*Open in code editor* to keep working by hand — the link back is one way).

## The four tabs

* **Objects** — object *types* (a picture, a color and a size), drawn on an 8 × 8 grid or picked from the sprite library.
  Tap *Place on the screen* and tap the stage to put objects there; tap an object to select it and drag to move it.
* **Rules** — what the game does. Each rule reads like a sentence: **WHEN** something happens, **IF** conditions hold, **DO** actions.
* **Game** — background color, **variables** (numbers such as *score* and *lives*, optionally shown on the screen) and project tools.
* **Code** — the generated program, with its QR size.

Press **▶ Test** to play the game right under the stage while you edit; everything is saved automatically on your device.

## Writing rules

Rules run from top to bottom, every frame. *Objects touch* and *reaches an edge* give the actions two helpers:
**this object** and **the other object**. A field that takes a number accepts a plain number *or any JavaScript expression*:
\`120\`, \`R(200)\` (random), \`a.x + 4\` (this object's x), \`score * 2\`, \`-Math.abs(b.vy)\`.
Text can contain \`{variable}\` placeholders, e.g. \`SCORE {score}\`.

Inside rules that have them, \`a\` is *this object* and \`b\` is *the other object*; objects have the fields \`x y vx vy w h c\`.

### WHEN (triggers)

| Name | Sentence |
|---|---|
${Object.entries(A.VB.trig).map(([k, v]) => `| ${A.VNAMES.trig[k]} | ${v.l.replace(/\{(\w+)\}/g, '*$1*')} |`).join('\n')}

### IF (conditions)

| Name | Sentence |
|---|---|
${Object.entries(A.VB.cond).map(([k, v]) => `| ${A.VNAMES.cond[k]} | ${v.l.replace(/\{(\w+)\}/g, '*$1*')} |`).join('\n')}

### DO (actions)

| Name | Sentence |
|---|---|
${Object.entries(A.VB.act).map(([k, v]) => `| ${A.VNAMES.act[k]} | ${v.l.replace(/\{(\w+)\}/g, '*$1*')} |`).join('\n')}

## Starter projects

${A.VTEMPLATES.map(t => `* **${t.name}** — ${t.about}`).join('\n')}

Open *Game → Project* to start from one of them.

## Using code and rules together

* **Run JavaScript** (an action) and **JavaScript test** (a condition) let you drop a line of code into any rule.
* The generated program uses the same library as hand-written games (\`kind\`, \`add\`, \`touch\`, \`each\`, \`step\`, \`draw\`…), so it is
  a good way to learn the language: make something visually, then read the *Code* tab.
`);
  return md(out.join('\n'));
}

function games(A) {
  const rows = A.GAMES.map(g => {
    const url = A.toURL(g.code), q = A.QR(A.urlSegs(url));
    return `| ${g.name} | ${g.about} | ${A.U8.encode(A.min(g.code)).length} B | ${url.length} | v${q.v} (${q.size}×${q.size}) |`;
  });
  return md(HEADER + `# Demo games and their QR codes

Every demo is a normal QRG program (see \`games/\`). The QR code holds the URL of the hosting page plus the compressed game, so scanning it
with any phone camera opens the game. Sizes are measured for the current compressor and the hosting URL \`${A.BASE}\`.

| Game | What it is | Code (minified) | URL length | QR code |
|---|---|---|---|---|
${rows.join('\n')}

A QR code holds at most about 4300 alphanumeric characters (version 40). Smaller QR codes scan faster and from further away:
version 10 is 57 × 57 modules, version 20 is 97 × 97, version 30 is 137 × 137.
`);
}

function generate() {
  const A = load();
  return { 'docs/LANGUAGE.md': language(A), 'docs/VISUAL.md': visual(A), 'docs/GAMES.md': games(A) };
}

if (require.main === module) {
  fs.mkdirSync(path.join(build.root, 'docs'), { recursive: true });
  for (const [f, text] of Object.entries(generate())) fs.writeFileSync(path.join(build.root, f), text);
  console.log('docs generated');
}
module.exports = { generate };
